import random
import pandas as pd
from solver import Algorithm
from typing import Tuple, List, Dict, Optional


class Evolved(Algorithm):
    """
    Prefix-cache-optimized reorderer with identical-row class collapse.

    Objective: maximize matched characters in a character Trie over serialized
    rows ("" join of fillna("").astype(str) cells). For a fixed multiset of row
    strings, ideal Trie reuse = sum of adjacent-LCPs of sorted strings, so rows
    are emitted in lexicographic order.

    Identical-row-collapse mechanism (this attempt's structural form): each
    row's full serialized string is built exactly once with a C-speed join and
    used directly as the equivalence-class key — no tuple construction, and the
    same strings are reused as the identity candidate's row strings. All
    construction (identity, frequency, conditional partition tree, fused-pair
    units) and all scoring operate on class representatives; the
    permutation-invariant intra-class reuse len(str)*(mult-1) is added once to
    the exact score. The budget guard evaluates unique-character volume, so
    duplicate-heavy frames re-enable the tree and local search. Emission
    expands every class to all member rows with the class permutation,
    preserving row count, cell values and per-row orderings exactly.
    On duplicate-free data this is behaviorally identical to the parent with
    near-zero added cost.

    Fusion candidate: up to 3 co-occurring column pairs fused into atomic
    units; the bounded local search gains additive unit-block moves alongside
    the column-level floor. Screening on a fixed representative subsample;
    acceptance by the exact whole-frame (unique + intra-class) score.
    """

    def __init__(self, df: pd.DataFrame = None):
        self.df = df
        self.colstr: List[List[str]] = []
        self.max_depth = 6
        self.cand_limit = 8
        self.suffix_greedy_steps = 3
        self._freq_weights: List[int] = []
        self._fused_units: Optional[List[Tuple[int, ...]]] = None
        # class-collapse state
        self.class_rows: List[List[int]] = []   # class id -> original row ids
        self.class_mult: List[int] = []         # multiplicity per class
        self.class_bonus: int = 0               # intra-class reuse (perm-invariant)
        self.rep_ids: List[int] = []            # one representative row id per class

    # ---------- serialization + class collapse ----------

    def _serialize(self, df: pd.DataFrame) -> None:
        """Serialize each column once (missing -> '') and collapse identical
        rows: the full serialized row string is built once per row with a
        C-speed join and used as the class key, so the collapse pass costs one
        join per row and yields the identity candidate's strings for free."""
        self.colstr = []
        for c in df.columns:
            out = []
            for v in df[c].tolist():
                if v is None or v is pd.NA or v is pd.NaT:
                    out.append("")
                elif isinstance(v, float) and v != v:
                    out.append("")
                else:
                    out.append(str(v))
            self.colstr.append(out)
        n = len(self.colstr[0]) if self.colstr else 0
        ncol = len(self.colstr)
        classes: Dict[str, int] = {}
        self.class_rows = []
        self.class_mult = []
        self.rep_ids = []
        self.class_bonus = 0
        cs = self.colstr
        for r in range(n):
            s = "".join([cs[j][r] for j in range(ncol)])
            cid = classes.get(s)
            if cid is None:
                cid = len(self.class_rows)
                classes[s] = cid
                self.class_rows.append([r])
                self.class_mult.append(1)
                self.rep_ids.append(r)
            else:
                self.class_rows[cid].append(r)
                self.class_mult[cid] += 1
        for cid, rows in enumerate(self.class_rows):
            mult = self.class_mult[cid]
            if mult > 1:
                r0 = rows[0]
                slen = sum(len(cs[j][r0]) for j in range(ncol))
                self.class_bonus += slen * (mult - 1)

    def _compute_freq_weights(self, ncol: int) -> None:
        """Per-column sum of len(v)*count*(count-1), computed over
        representatives weighted by class multiplicity (equivalent to the
        full-row computation, on m rows instead of n)."""
        m = len(self.rep_ids)
        mults = self.class_mult
        weights = []
        for j in range(ncol):
            col = self.colstr[j]
            cnt: Dict[str, int] = {}
            wsum: Dict[str, int] = {}
            for i in range(m):
                r = self.rep_ids[i]
                v = col[r]
                w = mults[i]
                cnt[v] = cnt.get(v, 0) + w
                wsum[v] = wsum.get(v, 0) + len(v) * w
            wt = 0
            for v, c in cnt.items():
                if c > 1:
                    wt += wsum[v] * (c - 1)
            weights.append(wt)
        self._freq_weights = weights

    # ---------- scoring ----------

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Longest common prefix via bounded binary search with C-speed slices."""
        if a == b:
            return len(a)
        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    def _score_sorted(self, strs: List[str]) -> int:
        """Adjacent-LCP sum over sorted representative strings plus the
        permutation-invariant intra-class reuse bonus."""
        total = self.class_bonus
        if not strs:
            return total
        prev = strs[0]
        for cur in strs[1:]:
            if cur == prev:
                total += len(cur)
            else:
                total += self._lcp(prev, cur)
            prev = cur
        return total

    # ---------- construction helpers (representatives only) ----------

    def _rows_strings(self, rep_positions: List[int], perms: List[Tuple[int, ...]]) -> List[str]:
        """Serialized strings for representative rows; C-speed joins."""
        cs = self.colstr
        return ["".join([cs[j][self.rep_ids[p]] for j in perm])
                for p, perm in zip(rep_positions, perms)]

    def _finalize(self, rep_positions, perms):
        """Sort classes lexicographically by serialized string; returns
        (sorted rep positions, per-class perms, sorted strings)."""
        pairs = sorted(
            zip(self._rows_strings(rep_positions, perms), rep_positions, perms),
            key=lambda t: t[0],
        )
        return [p[1] for p in pairs], [p[2] for p in pairs], [p[0] for p in pairs]

    def _cand_identity(self, m: int, ncol: int):
        perm = tuple(range(ncol))
        return self._finalize(list(range(m)), [perm] * m)

    def _cand_freq(self, m: int, ncol: int):
        """Global column order ranked by len*count*(count-1), deterministic ties."""
        perm = tuple(sorted(range(ncol), key=lambda j: (-self._freq_weights[j], j)))
        return self._finalize(list(range(m)), [perm] * m)

    # ---------- column-pair fusion ----------

    def _pair_units(self, ncol: int, m: int, mean_len: float) -> List[Tuple[int, ...]]:
        """Select <=3 non-overlapping co-occurring column pairs to fuse; one
        factorization per top-6 frequency column over representatives,
        affinity = min(len_a,len_b)*count*(count-1), measured internal order."""
        if ncol < 2 or m < 2:
            return []
        top = sorted(range(ncol), key=lambda j: (-self._freq_weights[j], j))[: min(ncol, 6)]
        codes: List[List[int]] = []
        clen: List[List[int]] = []
        ncodes: List[int] = []
        for j in top:
            col = self.colstr[j]
            mm: Dict[str, int] = {}
            cc: List[int] = []
            ll: List[int] = []
            for i in range(m):
                v = col[self.rep_ids[i]]
                code = mm.get(v)
                if code is None:
                    code = len(mm)
                    mm[v] = code
                    ll.append(len(v))
                cc.append(code)
            codes.append(cc)
            clen.append(ll)
            ncodes.append(len(mm))
        scored = []
        step = max(1, m // 4096)
        idxs = range(0, m, step)
        for ai in range(len(top)):
            for bi in range(ai + 1, len(top)):
                cnt: Dict[int, int] = {}
                base = ncodes[bi]
                for i in idxs:
                    key = codes[ai][i] * base + codes[bi][i]
                    cnt[key] = cnt.get(key, 0) + 1
                aff = 0
                for key, c in cnt.items():
                    if c > 1:
                        ca, cb = divmod(key, base)
                        aff += min(clen[ai][ca], clen[bi][cb]) * (c - 1)
                aff *= step
                if aff > 0.05 * mean_len * m and len(idxs) > 1:
                    scored.append((aff, top[ai], top[bi]))
        scored.sort(key=lambda t: (-t[0], t[1], t[2]))
        used: set = set()
        units: List[Tuple[int, ...]] = []
        for aff, a, b in scored:
            if a in used or b in used or len(units) >= 3:
                break
            used.add(a)
            used.add(b)
            ca, cb = self.colstr[a], self.colstr[b]
            rs = range(0, m, max(1, m // 2048))
            ab = sorted(ca[self.rep_ids[i]] + cb[self.rep_ids[i]] for i in rs)
            ba = sorted(cb[self.rep_ids[i]] + ca[self.rep_ids[i]] for i in rs)
            units.append((a, b) if self._score_sorted(ab) >= self._score_sorted(ba) else (b, a))
        return units

    def _cand_fused(self, ncol: int, m: int, budget_ok: bool):
        """Fused-pair candidate over representatives; stores units for the
        local search. Returns None when no pair qualifies."""
        self._fused_units = None
        if not budget_ok or m * ncol > 4_000_000:
            return None
        units = self._pair_units(ncol, m, self._mean_col_len(ncol, m))
        if not units:
            return None
        fused_of_col: Dict[int, int] = {}
        unit_members: List[Tuple[int, ...]] = []
        unit_weight: List[int] = []
        for members in units:
            uid = len(unit_members)
            for j in members:
                fused_of_col[j] = uid
            unit_members.append(members)
            unit_weight.append(sum(self._freq_weights[j] for j in members))
        for j in range(ncol):
            if j not in fused_of_col:
                fused_of_col[j] = len(unit_members)
                unit_members.append((j,))
                unit_weight.append(self._freq_weights[j])
        perm = tuple(
            j for u in sorted(range(len(unit_members)),
                              key=lambda u: (-unit_weight[u], unit_members[u][0]))
            for j in unit_members[u]
        )
        self._fused_units = unit_members
        return self._finalize(list(range(m)), [perm] * m)

    def _mean_col_len(self, ncol: int, m: int) -> float:
        """Mean serialized cell length over representatives."""
        total = count = 0
        step = max(1, m // 1024)
        for j in range(ncol):
            col = self.colstr[j]
            for i in range(0, m, step):
                total += len(col[self.rep_ids[i]])
                count += 1
        return total / count if count else 0.0

    # ---------- conditional partition tree ----------

    def _node_lcp_gain(self, positions: List[int], j: int) -> int:
        """Measured adjacent-LCP sum over the node's sorted values for column j."""
        col = self.colstr[j]
        vals = sorted(col[self.rep_ids[i]] for i in positions)
        uniq: List[str] = []
        dup_len = 0
        prev = None
        for v in vals:
            if v == prev:
                dup_len += len(v)
            else:
                uniq.append(v)
                prev = v
        total = dup_len
        for i in range(1, len(uniq)):
            total += self._lcp(uniq[i - 1], uniq[i])
        return total

    def _group_freq_order(self, positions: List[int], remaining: List[int]) -> List[int]:
        """Within-group length-weighted repetition suffix order (mult-weighted)."""
        cs = self.colstr
        mults = self.class_mult
        weights = []
        for j in remaining:
            col = cs[j]
            cnt: Dict[str, int] = {}
            wsum: Dict[str, int] = {}
            for i in positions:
                v = col[self.rep_ids[i]]
                w = mults[i]
                cnt[v] = cnt.get(v, 0) + w
                wsum[v] = wsum.get(v, 0) + len(v) * w
            wt = 0
            for v, c in cnt.items():
                if c > 1:
                    wt += wsum[v] * (c - 1)
            weights.append(wt)
        return [j for _, j in sorted(zip(weights, remaining), key=lambda t: (-t[0], t[1]))]

    def _group_suffix_order(self, positions: List[int], remaining: List[int]) -> List[int]:
        """Measured greedy suffix ordering (bounded steps), frequency tail."""
        small = len(positions) < 2 or len(remaining) <= 1
        picked: List[int] = []
        rem = list(remaining)
        if not small:
            for _ in range(min(self.suffix_greedy_steps, len(rem) - 1)):
                best_j, best_gain = None, 0
                for j in rem[: self.cand_limit]:
                    g = self._node_lcp_gain(positions, j)
                    if g > best_gain:
                        best_gain, best_j = g, j
                if best_j is None:
                    break
                picked.append(best_j)
                rem.remove(best_j)
        picked.extend(self._group_freq_order(positions, rem))
        return picked

    def _cand_tree(self, ncol: int):
        """Conditional prefix partition tree over class representatives.
        Leading column chosen by measured adjacent-LCP savings, rows partitioned
        by value, leaves get measured-suffix orders. Depth/candidates bounded;
        no full row-string LCP scoring inside the tree loop."""

        def node(positions: List[int], remaining: List[int], prefix: Tuple[int, ...]):
            if len(positions) < 2 or not remaining or len(prefix) >= self.max_depth:
                return [(prefix + tuple(self._group_suffix_order(positions, remaining)), positions)]
            best_j, best_gain = None, 0
            for j in remaining[: self.cand_limit]:
                g = self._node_lcp_gain(positions, j)
                if g > best_gain:
                    best_gain, best_j = g, j
            if best_j is None:
                return [(prefix + tuple(self._group_suffix_order(positions, remaining)), positions)]
            groups: Dict[str, List[int]] = {}
            col = self.colstr[best_j]
            for i in positions:
                groups.setdefault(col[self.rep_ids[i]], []).append(i)
            if len(groups) >= len(positions):
                return [(prefix + tuple(self._group_suffix_order(positions, remaining)), positions)]
            rem = [j for j in remaining if j != best_j]
            out = []
            for key in sorted(groups):
                out.extend(node(groups[key], rem, prefix + (best_j,)))
            return out

        m = len(self.rep_ids)
        perms: List[Tuple[int, ...]] = [None] * m
        for perm, positions in node(list(range(m)), list(range(ncol)), ()):
            for i in positions:
                perms[i] = perm
        return self._finalize(list(range(m)), perms)

    # ---------- local search ----------

    @staticmethod
    def _block_swap_candidates(perm: Tuple[int, ...], cap: int) -> List[Tuple[int, ...]]:
        """Deterministic grid of contiguous-block exchange moves (widths 1-3)."""
        n = len(perm)
        cands: List[Tuple[int, ...]] = []
        seen = set()
        for w in (1, 2, 3):
            if 2 * w > n:
                break
            positions = sorted({round(k * (n - 2 * w) / 4) for k in range(5)})
            for i in positions:
                if i < 0 or i + w > n:
                    continue
                for j in positions:
                    if j <= i + w - 1 or j + w > n:
                        continue
                    cand = perm[:i] + perm[j:j + w] + perm[i + w:j] + perm[i:i + w] + perm[j + w:]
                    if cand in seen or cand == perm:
                        continue
                    seen.add(cand)
                    cands.append(cand)
                    if len(cands) >= cap:
                        return cands
        return cands

    def _local_search(
        self,
        seed_perm: Tuple[int, ...],
        budget_ok: bool,
        rng: random.Random,
        units: Optional[List[Tuple[int, ...]]] = None,
    ) -> Optional[Tuple[Tuple[int, ...], int]]:
        """Bounded steepest-descent on a uniform permutation over classes.
        Column-level candidates (front-promotion, adjacent transpositions,
        block exchanges) plus ADDITIVE unit-block moves when a fused-unit
        decomposition exists and the seed is unit-consistent. Sample screening
        on a fixed representative subsample; acceptance by exact score."""
        m = len(self.rep_ids)
        ncol = len(seed_perm)
        if not budget_ok or m < 2 or ncol < 2:
            return None

        blocks: Optional[List[Tuple[int, ...]]] = None
        if units:
            i = 0
            blocks = []
            ok = True
            while i < ncol:
                matched = None
                for u in units:
                    if tuple(seed_perm[i:i + len(u)]) == u:
                        matched = u
                        break
                if matched is None:
                    ok = False
                    break
                blocks.append(matched)
                i += len(matched)
            if not ok or len(blocks) == ncol:
                blocks = None

        sample_m = min(m, 1024)
        if sample_m < m:
            sample_pos = rng.sample(range(m), sample_m)
            sample_pos.sort()
        else:
            sample_pos = list(range(m))

        def full_score(perm: Tuple[int, ...]) -> int:
            _, _, strs = self._finalize(list(range(m)), [perm] * m)
            return self._score_sorted(strs)

        def sample_score(perm: Tuple[int, ...]) -> int:
            strs = sorted(self._rows_strings(sample_pos, [perm] * sample_m))
            return self._score_sorted(strs)

        def expand(block_perm: Tuple[Tuple[int, ...], ...]) -> Tuple[int, ...]:
            out: List[int] = []
            for b in block_perm:
                out.extend(b)
            return tuple(out)

        def reblock(best_perm: Tuple[int, ...]) -> Optional[List[Tuple[int, ...]]]:
            if blocks is None:
                return None
            i2 = 0
            nb: List[Tuple[int, ...]] = []
            while i2 < ncol:
                for u in blocks:
                    if tuple(best_perm[i2:i2 + len(u)]) == u:
                        nb.append(u)
                        break
                else:
                    return None
                i2 += len(nb[-1])
            return nb

        best_perm = seed_perm
        best_score = full_score(seed_perm)
        best_sample = sample_score(seed_perm)
        moves_cap = min(ncol, 12)
        sweeps = 0
        while sweeps < 2:
            sweeps += 1
            improved = False
            for j in list(best_perm)[:moves_cap]:
                cand = tuple([j] + [k for k in best_perm if k != j])
                if cand == best_perm:
                    continue
                if sample_score(cand) <= best_sample:
                    continue
                s = full_score(cand)
                if s > best_score:
                    best_score = s
                    best_sample = sample_score(cand)
                    best_perm = cand
                    blocks = reblock(best_perm)
                    improved = True
            trans_candidates: List[Tuple[int, ...]] = []
            for i in range(min(ncol - 1, moves_cap)):
                cand = list(best_perm)
                cand[i], cand[i + 1] = cand[i + 1], cand[i]
                trans_candidates.append(tuple(cand))
            half = max(1, moves_cap // 2)
            trans_candidates.extend(
                self._block_swap_candidates(best_perm, moves_cap - min(ncol - 1, moves_cap) + half)
            )
            if blocks is not None and len(blocks) >= 2:
                nb = len(blocks)
                btuple = tuple(blocks)
                for u in blocks:
                    trans_candidates.append(expand(tuple([u] + [b for b in blocks if b != u])))
                for i in range(nb - 1):
                    bl = list(blocks)
                    bl[i], bl[i + 1] = bl[i + 1], bl[i]
                    trans_candidates.append(expand(tuple(bl)))
                for bs in self._block_swap_candidates(btuple, max(1, moves_cap // 2)):
                    trans_candidates.append(expand(bs))
            seen: set = set()
            deduped = []
            for cand in trans_candidates:
                if cand not in seen and cand != best_perm:
                    seen.add(cand)
                    deduped.append(cand)
            for cand in deduped[: 2 * moves_cap]:
                if sample_score(cand) <= best_sample:
                    continue
                s = full_score(cand)
                if s > best_score:
                    best_score = s
                    best_sample = sample_score(cand)
                    best_perm = cand
                    blocks = reblock(best_perm)
                    improved = True
            if not improved:
                break
        return best_perm, best_score

    # ---------- public API ----------

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Produce the row/field ordering maximizing serial character-Trie reuse.
        Identical-row classes are collapsed once during serialization; bounded
        construction selection (identity, frequency, conditional tree, fused
        units) runs on class representatives with one exact sorted-LCP score
        each, followed by the shared bounded local search; classes expand back
        to all member rows at emission."""
        if col_merge:
            self.num_rows, self.column_stats = self.calculate_col_stats(df, enable_index=True)
            reordered_columns = [c for c, _, _, _ in self.column_stats]
            for col_to_merge in col_merge:
                final_col_order = [c for c in reordered_columns if c in col_to_merge]
                df = self.merging_columns(df, final_col_order, prepended=False)

        n, ncol = df.shape
        cols = list(df.columns)
        if n == 0 or ncol == 0:
            return df.copy(), [[] for _ in range(n)]

        self._serialize(df)
        m = len(self.rep_ids)
        self._compute_freq_weights(ncol)

        # Budget on unique-character volume: duplication shrinks the effective
        # frame, re-enabling the tree and local search on duplicate-heavy data.
        budget_ok = True
        if m * ncol > 200_000:
            step = max(1, m // 512)
            sample_len = 0
            cnt = 0
            for j in range(ncol):
                col = self.colstr[j]
                for i in range(0, m, step):
                    sample_len += len(col[self.rep_ids[i]])
                    cnt += 1
            mean_len = sample_len / max(1, cnt)
            budget_ok = m * ncol * mean_len <= 2_000_000

        candidates = [self._cand_identity(m, ncol), self._cand_freq(m, ncol)]
        if m * ncol <= 4_000_000:
            candidates.append(self._cand_tree(ncol))
            fused = self._cand_fused(ncol, m, budget_ok)
            if fused is not None:
                candidates.append(fused)

        best_pos_order: List[int] = list(range(m))
        best_class_perms: List[Tuple[int, ...]] = [tuple(range(ncol))] * m
        best_score = -1
        best_uniform_perm: Optional[Tuple[int, ...]] = None
        fused_units: Optional[List[Tuple[int, ...]]] = None
        for pos_order, class_perms, strs in candidates:
            score = self._score_sorted(strs)
            if score > best_score:
                best_score = score
                best_pos_order, best_class_perms = pos_order, class_perms
                if class_perms and all(p == class_perms[0] for p in class_perms):
                    best_uniform_perm = class_perms[0]
                    fused_units = self._fused_units if self._units_match(class_perms[0]) else None
                else:
                    best_uniform_perm = None
                    fused_units = None

        if best_uniform_perm is None:
            best_uniform_perm = tuple(
                sorted(range(ncol), key=lambda j: (-self._freq_weights[j], j))
            )
        rng = random.Random(12345)
        ls = self._local_search(best_uniform_perm, budget_ok, rng, units=fused_units)
        if ls is not None:
            ls_perm, ls_score = ls
            if ls_score > best_score:
                best_pos_order, best_class_perms, _ = self._finalize(
                    list(range(m)), [ls_perm] * m
                )

        # Emission: expand every class to all member rows, in sorted class
        # order, with the class permutation. All original rows/cells preserved.
        raw_cols = [self.colstr[j] for j in range(ncol)]
        data = []
        orderings = []
        for pos in best_pos_order:
            perm = best_class_perms[pos]
            rows = self.class_rows[pos]
            col_names = [cols[j] for j in perm]
            col_lists = [raw_cols[j] for j in perm]
            for r in rows:
                data.append([cl[r] for cl in col_lists])
                orderings.append(col_names)
        out = pd.DataFrame(data, columns=[f"c{i}" for i in range(ncol)], dtype=object)
        return out, orderings

    def _units_match(self, perm: Tuple[int, ...]) -> bool:
        """Check whether the permutation is a concatenation of stored fused
        units (each unit's members contiguous, in internal order)."""
        units = self._fused_units
        if not units:
            return False
        i = 0
        while i < len(perm):
            for u in units:
                if tuple(perm[i:i + len(u)]) == u:
                    i += len(u)
                    break
            else:
                return False
        return True

